// FR-001-AC2, FR-001-AC7 | Negative / Boundary
// Seeded user customer3@retailqe.test (UserId 4) already has 5 failed attempts.
// This request sends the CORRECT password; the account must be refused as locked.
const baseUrl = pm.variables.get('base_url');

const message = (res) => {
  try {
    const b = res.json();
    return String(b.message || b.error || '');
  } catch (e) {
    return '';
  }
};

pm.test('T-API-AUTH-002: correct password on the locked account is refused (423/403)', function () {
  pm.expect(pm.response.code, 'status').to.be.oneOf([423, 403]);
});

pm.test('response gives a lockout message', function () {
  pm.expect(message(pm.response)).to.match(/lock/i);
});

pm.test('no token is issued for the locked account', function () {
  pm.expect(pm.response.text()).to.not.include('"token"');
});

pm.test('a different user (customer1) can still log in', function (done) {
  pm.sendRequest(
    {
      url: baseUrl + '/auth/login',
      method: 'POST',
      header: { 'Content-Type': 'application/json' },
      body: {
        mode: 'raw',
        raw: JSON.stringify({ email: 'customer1@retailqe.test', password: 'Pass123!' }),
      },
    },
    function (err, res) {
      try {
        pm.expect(err, 'request error').to.be.null;
        pm.expect(res.code, 'status').to.equal(200);
        done();
      } catch (e) {
        done(e);
      }
    }
  );
});

