// Step 1-2: log in, store the token, and check it works before logout
const api = pm.variables.get('baseURL').replace(/\/$/, '') + '/api';

pm.sendRequest(
  {
    url: api + '/auth/login',
    method: 'POST',
    header: { 'Content-Type': 'application/json' },
    body: {
      mode: 'raw',
      raw: JSON.stringify({ email: 'customer1@retailqe.test', password: 'Pass123!' }),
    },
  },
  (err, res) => {
    const body = res.json();
    const protectedUrl = api + '/customers/' + body.user.customerId;
    pm.environment.set('auth_token', body.token);
    pm.environment.set('protected_url', protectedUrl);

    pm.sendRequest(
      { url: protectedUrl, method: 'GET', header: { Authorization: 'Bearer ' + body.token } },
      (e, r) => pm.environment.set('code_before_logout', r.code)
    );
  }
);

