// FR-001-AC6 | Positive / Negative
// Request = password-reset for a known email. The script also checks an unknown email and a missing email.
const api = pm.variables.get('baseURL').replace(/\/$/, '') + '/api';
const GENERIC = /if the account exists/i;

const messageOf = (res) => {
  try {
    const b = res.json();
    return String(b.message || b.error || '');
  } catch (e) {
    return '';
  }
};

pm.test('T-API-AUTH-004: known email returns 200 with a generic reset message', function () {
  pm.expect(pm.response.code, 'status').to.equal(200);
  pm.expect(messageOf(pm.response)).to.match(GENERIC);
});

pm.test('the response does not expose a reset token', function () {
  const raw = pm.response.text().toLowerCase();
  pm.expect(raw).to.not.include('token');
});

const post = (payload, cb) =>
  pm.sendRequest(
    {
      url: api + '/auth/password-reset',
      method: 'POST',
      header: { 'Content-Type': 'application/json' },
      body: { mode: 'raw', raw: JSON.stringify(payload) },
    },
    cb
  );

post({ email: pm.environment.get('unknown_email') }, (err1, unknown) => {
  post({}, (err2, missing) => {
    pm.test('unknown email gets the same generic response (no account enumeration)', function () {
      pm.expect(err1, 'request error').to.be.null;
      pm.expect(unknown.code, 'status').to.equal(pm.response.code);
      pm.expect(messageOf(unknown), 'message').to.equal(messageOf(pm.response));
    });

    pm.test('missing email is rejected with 400', function () {
      pm.expect(err2, 'request error').to.be.null;
      pm.expect(missing.code).to.equal(400);
    });
  });
});

