// Log in to get a real token, then build the tampered and expired versions
pm.sendRequest({
  url: base + '/auth/login', method: 'POST',
  header: { 'Content-Type': 'application/json' },
  body: { mode: 'raw', raw: JSON.stringify({
    email: pm.variables.get('customer_email') || 'customer1@retailqe.test',
    password: pm.variables.get('customer_password') || 'Pass123!' }) }
}, (e, r) => {
  let token = null; try { token = r.json().token; } catch (x) {}
  if (e || !token) return console.error('Login failed, cannot build tokens', e, r && r.code, r && r.text());

  const parts = token.split('.');
  const b64u = s => s.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - s.length % 4) % 4);
  const enc = o => btoa(JSON.stringify(o)).replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');

  // Step 2: tampered token (alter the first character of the signature)
  pm.variables.set('tampered_token', parts.length === 3
    ? parts[0] + '.' + parts[1] + '.' + parts[2].replace(/^./, c => c === 'A' ? 'B' : 'A')
    : token + 'x');

  // Step 3: expired token (exp set one hour in the past)
  if (parts.length === 3) {
    try {
      const payload = JSON.parse(atob(b64u(parts[1])));
      payload.exp = Math.floor(Date.now() / 1000) - 3600;
      pm.variables.set('expired_token', parts[0] + '.' + enc(payload) + '.' + parts[2]);
    } catch (x) { console.error('Could not build expired token', x); }
  }
});

